package com.ibm.fxsort;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point for the modernized FXSORT application.
 * The original COBOL program performed:
 *   1. MERGE  three flat files on ASCENDING KEY FX-NAME  → FXLIST-MERGE
 *   2. SORT   the merged output on ASCENDING KEY FX-PRICE → FXLIST-SORTED
 *   3. STOP RUN
 *
 * This Spring Boot application reproduces the same logic using
 * PostgreSQL tables and JPA repositories.
 */
@SpringBootApplication
public class FxsortApplication {
    public static void main(String[] args) {
        SpringApplication.run(FxsortApplication.class, args);
    }
}

