package com.ibm.fxsort.model;

import jakarta.persistence.*;
import lombok.*;

import java.math.BigDecimal;

/**
 * Canonical FX record.
 * Maps to fx_boss, fx_mxr, fx_jhs, fx_merged, and fx_sorted
 * via the @Table annotation on each concrete entity.
 *
 * COBOL layout:
 *   05 FX-NAME   PIC X(50)
 *   05 FX-PRICE  PIC $$,$$$,$$9.99   (formatted currency — stored as NUMERIC)
 */
@MappedSuperclass
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@ToString
public abstract class FxRecord {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** Corresponds to FX-NAME-* PIC X(50) */
    @Column(name = "fx_name", nullable = false, length = 50)
    private String fxName;

    /** Corresponds to FX-PRICE-* PIC $$,$$$,$$9.99 */
    @Column(name = "fx_price", nullable = false, precision = 11, scale = 2)
    private BigDecimal fxPrice;
}

