/**
 * Repository for the MERGE output (FXLIST-MERGE / FXLSTMRG).
 * The COBOL MERGE verb combines and sorts the three USING files
 * on ASCENDING KEY FX-NAME before writing to the GIVING file.
 */
@Repository
public interface FxMergedRepository extends JpaRepository<FxMerged, Long> {

    /** Read merged records ordered by fxName ASC — feeds the subsequent SORT. */
