package com.ibm.fxsort.service;

import com.ibm.fxsort.model.*;
import com.ibm.fxsort.repository.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.text.DecimalFormat;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Stream;

/**
 * Service that reproduces the exact business logic of the COBOL FXSORT program.
 *
 * COBOL PROCEDURE DIVISION — PROCESS-RECORDS paragraph:
 * ───────────────────────────────────────────────────────
 *   DISPLAY "MERGING FILES"
 *   MERGE FXLIST-WORK ON ASCENDING KEY FX-NAME-W IN FX-REC
 *       USING FXLIST-B, FXLIST-M, FXLIST-J
 *       GIVING FXLIST-MERGE
 *
 *   DISPLAY "SORTING RECORDS".
 *   SORT FXLIST-WORK ON ASCENDING KEY FX-PRICE-W IN FX-REC
 *       USING FXLIST-MERGE
 *       GIVING FXLIST-SORTED
 *
 * COBOL CLOSE-STOP paragraph:
 * ───────────────────────────
 *   DISPLAY "NOW I'M STOPPING".
 *   STOP RUN.
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class FxSortService {

    private final FxBossRepository   fxBossRepository;
    private final FxMxrRepository    fxMxrRepository;
    private final FxJhsRepository    fxJhsRepository;
    private final FxMergedRepository  fxMergedRepository;
    private final FxSortedRepository  fxSortedRepository;

    /**
     * Entry point — maps 1-to-1 to the COBOL PROCESS-RECORDS paragraph.
     *
     * Step 1 → mergeFiles()  : MERGE … GIVING FXLIST-MERGE
     * Step 2 → sortRecords() : SORT  … GIVING FXLIST-SORTED
     * Step 3 → closeStop()   : DISPLAY "NOW I'M STOPPING" + STOP RUN
     */
    @Transactional
    public void processRecords() {
        mergeFiles();
        sortRecords();
        closeStop();
    }

    // ──────────────────────────────────────────────────────────────
    // STEP 1 — MERGING FILES
    // Replicates: MERGE FXLIST-WORK ON ASCENDING KEY FX-NAME-W
    //             USING FXLIST-B, FXLIST-M, FXLIST-J
    //             GIVING FXLIST-MERGE
    //
    // The COBOL MERGE verb performs an ordered merge of already-sorted
    // (or not necessarily sorted) input files; the result is a single
    // stream ordered by the KEY field.  We implement this by:
    //   a) reading all three source tables,
    //   b) combining into one stream,
    //   c) sorting by fxName ASC (stable, matching ASCENDING KEY),
    //   d) persisting to fx_merged.
    // ──────────────────────────────────────────────────────────────
    private void mergeFiles() {
        log.info("MERGING FILES");  // DISPLAY "MERGING FILES"

        // Read all three input sources ordered by name
        List<FxBoss> bossRecords = fxBossRepository.findAllByOrderByFxNameAsc();
        List<FxMxr>  mxrRecords  = fxMxrRepository.findAllByOrderByFxNameAsc();
        List<FxJhs>  jhsRecords  = fxJhsRepository.findAllByOrderByFxNameAsc();

        // Combine — USING FXLIST-B, FXLIST-M, FXLIST-J — then sort by FX-NAME ASC
        List<FxMerged> merged = Stream.of(
                    bossRecords.stream().map(r -> new FxMerged(r.getFxName(), r.getFxPrice())),
                    mxrRecords .stream().map(r -> new FxMerged(r.getFxName(), r.getFxPrice())),
                    jhsRecords .stream().map(r -> new FxMerged(r.getFxName(), r.getFxPrice()))
                )
                .flatMap(s -> s)
                .sorted(Comparator.comparing(FxMerged::getFxName))  // ASCENDING KEY FX-NAME
                .toList();

        // Persist to fx_merged (GIVING FXLIST-MERGE)
        fxMergedRepository.truncate();
        fxMergedRepository.saveAll(merged);

        log.info("Merge complete — {} records written to fx_merged", merged.size());
    }

    // ──────────────────────────────────────────────────────────────
    // STEP 2 — SORTING RECORDS
    // Replicates: SORT FXLIST-WORK ON ASCENDING KEY FX-PRICE-W
    //             USING FXLIST-MERGE
    //             GIVING FXLIST-SORTED
    //
    // The COBOL SORT verb reads the USING file and writes a sorted
    // copy to the GIVING file ordered by the KEY field.
    // We implement this by:
    //   a) reading fx_merged (already populated in step 1),
    //   b) sorting by fxPrice ASC (stable, matching ASCENDING KEY),
    //   c) persisting to fx_sorted.
    // ──────────────────────────────────────────────────────────────
    private void sortRecords() {
        log.info("SORTING RECORDS");  // DISPLAY "SORTING RECORDS"

        // Read the merge output
        List<FxMerged> mergedRecords = fxMergedRepository.findAllByOrderByFxNameAsc();

        // Sort by FX-PRICE ASC — ASCENDING KEY FX-PRICE-W
        List<FxSorted> sorted = mergedRecords.stream()
                .sorted(Comparator.comparing(FxMerged::getFxPrice))
                .map(r -> new FxSorted(r.getFxName(), r.getFxPrice()))
                .toList();

        // Persist to fx_sorted (GIVING FXLIST-SORTED)
        fxSortedRepository.truncate();
        fxSortedRepository.saveAll(sorted);

        log.info("Sort complete — {} records written to fx_sorted", sorted.size());

        // Log the final output for visibility (mirrors the flat-file content)
        logSortedOutput(sorted);
    }

    // ──────────────────────────────────────────────────────────────
    // STEP 3 — CLOSE-STOP paragraph
    // Replicates:
    //   DISPLAY "NOW I'M STOPPING".
    //   STOP RUN.
    // ──────────────────────────────────────────────────────────────
    private void closeStop() {
        log.info("NOW I'M STOPPING");  // DISPLAY "NOW I'M STOPPING"
        // STOP RUN — the application exits naturally after the runner completes.
    }

    // ──────────────────────────────────────────────────────────────
    // Helper — format and log each sorted record in a layout that
    // mirrors the COBOL FD (FX-NAME PIC X(50) + FX-PRICE $$,$$$,$$9.99)
    // ──────────────────────────────────────────────────────────────
    private void logSortedOutput(List<FxSorted> records) {
        DecimalFormat priceFmt = new DecimalFormat("$#,##0.00");
        log.info("─── Sorted FX Output ───────────────────────────────────────");
        for (FxSorted rec : records) {
            // Left-pad name to 50 chars; right-align price in 13 chars
            String namePadded  = String.format("%-50s", rec.getFxName());
            String priceFormatted = String.format("%13s", priceFmt.format(rec.getFxPrice()));
            log.info("{}{}", namePadded, priceFormatted);
        }
        log.info("────────────────────────────────────────────────────────────");
    }
}

