package com.ibm.fxsort.config;

import com.ibm.fxsort.model.*;
import com.ibm.fxsort.repository.*;
import com.opencsv.CSVReader;
import com.opencsv.exceptions.CsvException;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.core.annotation.Order;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.io.IOException;
import java.io.InputStreamReader;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * Loads seed data from classpath CSV files into the three input tables
 * before the main FXSORT logic runs.  This replaces the flat files
 * (FXBOSS, FXMXR, FXJHS) that were assigned via FILE-CONTROL in COBOL.
 *
 * CSV format per file: fx_name,fx_price
 * e.g.:  EUR/USD,1.0823
 *
 * Runs with @Order(1) so that the FxSortRunner (order 2) sees populated tables.
 */
@Slf4j
@Component
@Order(1)
@RequiredArgsConstructor
public class AppConfig implements ApplicationRunner {

    private final FxBossRepository fxBossRepository;
    private final FxMxrRepository  fxMxrRepository;
    private final FxJhsRepository  fxJhsRepository;

    @Override
    @Transactional
    public void run(ApplicationArguments args) throws Exception {
        log.info("Loading seed data from CSV files...");
        loadBoss();
        loadMxr();
        loadJhs();
        log.info("Seed data loaded.");
    }

    private void loadBoss() throws IOException, CsvException {
        if (fxBossRepository.count() > 0) {
            log.info("fx_boss already populated, skipping load.");
            return;
        }
        List<FxBoss> records = new ArrayList<>();
        try (CSVReader reader = csvReader("data-boss.csv")) {
            for (String[] row : reader.readAll()) {
                if (row.length < 2) continue;
                records.add(new FxBoss(row[0].trim(), new BigDecimal(row[1].trim())));
            }
        }
        fxBossRepository.saveAll(records);
        log.info("Loaded {} records into fx_boss", records.size());
    }

    private void loadMxr() throws IOException, CsvException {
        if (fxMxrRepository.count() > 0) {
            log.info("fx_mxr already populated, skipping load.");
            return;
        }
        List<FxMxr> records = new ArrayList<>();
        try (CSVReader reader = csvReader("data-mxr.csv")) {
            for (String[] row : reader.readAll()) {
                if (row.length < 2) continue;
                records.add(new FxMxr(row[0].trim(), new BigDecimal(row[1].trim())));
            }
        }
        fxMxrRepository.saveAll(records);
        log.info("Loaded {} records into fx_mxr", records.size());
    }

    private void loadJhs() throws IOException, CsvException {
        if (fxJhsRepository.count() > 0) {
            log.info("fx_jhs already populated, skipping load.");
            return;
        }
        List<FxJhs> records = new ArrayList<>();
        try (CSVReader reader = csvReader("data-jhs.csv")) {
            for (String[] row : reader.readAll()) {
                if (row.length < 2) continue;
                records.add(new FxJhs(row[0].trim(), new BigDecimal(row[1].trim())));
            }
        }
        fxJhsRepository.saveAll(records);
        log.info("Loaded {} records into fx_jhs", records.size());
    }

    private CSVReader csvReader(String classpathFile) throws IOException {
        return new CSVReader(
                new InputStreamReader(
                        new ClassPathResource(classpathFile).getInputStream(),
                        StandardCharsets.UTF_8));
    }
}

