package com.ibm.fxsort.runner;

import com.ibm.fxsort.service.FxSortService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

/**
 * Application runner that invokes the FxSortService after seed data is loaded.
 * Maps to the COBOL implicit top-level program flow:
 *   PROCESS-RECORDS → CLOSE-STOP → STOP RUN
 *
 * Runs with @Order(2) to ensure AppConfig (order 1) has seeded the data first.
 */
@Slf4j
@Component
@Order(2)
@RequiredArgsConstructor
public class FxSortRunner implements ApplicationRunner {

    private final FxSortService fxSortService;

    @Override
    public void run(ApplicationArguments args) {
        log.info("=== FXSORT starting ===");
        try {
            fxSortService.processRecords();
        } catch (Exception ex) {
            log.error("FXSORT encountered a fatal error: {}", ex.getMessage(), ex);
            throw ex;
        }
        log.info("=== FXSORT complete ===");
    }
}

